CREATE SCHEMA IF NOT EXISTS hostel_q5; SET search_path TO hostel_q5,public;
CREATE TABLE IF NOT EXISTS students(student_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_number TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(room_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_number TEXT UNIQUE NOT NULL,capacity INT NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS allocations(allocation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES students,room_id INT NOT NULL REFERENCES rooms,allocated_on DATE NOT NULL,released_on DATE,status TEXT NOT NULL CHECK(status IN('ACTIVE','ENDED')),CHECK((status='ACTIVE' AND released_on IS NULL) OR (status='ENDED' AND released_on IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS uq_one_active_allocation_student ON allocations(student_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS occupancy_snapshot(snapshot_date DATE NOT NULL,room_id INT NOT NULL REFERENCES rooms,occupied_beds INT NOT NULL,free_beds INT NOT NULL,PRIMARY KEY(snapshot_date,room_id));
INSERT INTO students VALUES(1,'HS001','Student One'),(2,'HS002','Student Two'),(3,'HS003','Student Three'),(4,'HS004','Student Four') ON CONFLICT DO NOTHING;
INSERT INTO rooms VALUES(1,'A1',2),(2,'A2',3),(3,'A3',1) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_free_beds(p_room_id INT) RETURNS INT LANGUAGE plpgsql AS $$
DECLARE c INT; n INT; BEGIN SELECT capacity INTO c FROM rooms WHERE room_id=p_room_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown room'; END IF; SELECT count(*) INTO n FROM allocations WHERE room_id=p_room_id AND status='ACTIVE'; RETURN c-n; END $$;
CREATE OR REPLACE FUNCTION fn_validate_allocation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cap INT; used INT; BEGIN IF NEW.status='ACTIVE' THEN SELECT capacity INTO cap FROM rooms WHERE room_id=NEW.room_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown room'; END IF; IF EXISTS(SELECT 1 FROM allocations a WHERE a.student_id=NEW.student_id AND a.status='ACTIVE' AND a.allocation_id IS DISTINCT FROM NEW.allocation_id) THEN RAISE EXCEPTION 'Student already has an active allocation'; END IF; SELECT count(*) INTO used FROM allocations a WHERE a.room_id=NEW.room_id AND a.status='ACTIVE' AND a.allocation_id IS DISTINCT FROM NEW.allocation_id; IF used>=cap THEN RAISE EXCEPTION 'Room capacity exceeded'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_validate_allocation ON allocations;
CREATE TRIGGER trg_validate_allocation BEFORE INSERT OR UPDATE ON allocations FOR EACH ROW EXECUTE FUNCTION fn_validate_allocation();
CREATE OR REPLACE PROCEDURE pr_allocate_room(p_student_id INT,p_room_id INT,p_allocated_on DATE) LANGUAGE plpgsql AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM students WHERE student_id=p_student_id) THEN RAISE EXCEPTION 'Unknown student'; END IF; IF NOT EXISTS(SELECT 1 FROM rooms WHERE room_id=p_room_id) THEN RAISE EXCEPTION 'Unknown room'; END IF; IF p_allocated_on IS NULL THEN RAISE EXCEPTION 'Allocation date required'; END IF; IF EXISTS(SELECT 1 FROM allocations WHERE student_id=p_student_id AND status='ACTIVE') THEN RAISE EXCEPTION 'Student already allocated'; END IF; IF fn_free_beds(p_room_id)<=0 THEN RAISE EXCEPTION 'No free beds'; END IF; INSERT INTO allocations(student_id,room_id,allocated_on,status) VALUES(p_student_id,p_room_id,p_allocated_on,'ACTIVE'); END $$;
INSERT INTO allocations(student_id,room_id,allocated_on,status) VALUES(1,1,CURRENT_DATE,'ACTIVE'),(2,1,CURRENT_DATE,'ACTIVE'),(3,2,CURRENT_DATE,'ACTIVE'),(4,2,CURRENT_DATE-30,CURRENT_DATE-1,'ENDED') ON CONFLICT DO NOTHING;
CREATE OR REPLACE VIEW v_room_occupancy AS SELECT r.room_id,r.room_number,r.capacity,count(a.allocation_id) FILTER(WHERE a.status='ACTIVE') AS occupied_beds,r.capacity-count(a.allocation_id) FILTER(WHERE a.status='ACTIVE') AS free_beds FROM rooms r LEFT JOIN allocations a USING(room_id) GROUP BY r.room_id;
CREATE INDEX IF NOT EXISTS ix_allocations_active_room ON allocations(room_id) WHERE status='ACTIVE';
EXPLAIN SELECT * FROM allocations WHERE room_id=1 AND status='ACTIVE';
CREATE OR REPLACE PROCEDURE pr_refresh_occupancy() LANGUAGE plpgsql AS $$
BEGIN INSERT INTO occupancy_snapshot SELECT CURRENT_DATE,room_id,count(a.allocation_id) FILTER(WHERE a.status='ACTIVE'),capacity-count(a.allocation_id) FILTER(WHERE a.status='ACTIVE') FROM rooms r LEFT JOIN allocations a USING(room_id) GROUP BY room_id,capacity ON CONFLICT(snapshot_date,room_id) DO UPDATE SET occupied_beds=EXCLUDED.occupied_beds,free_beds=EXCLUDED.free_beds; END $$;
CALL pr_refresh_occupancy();
-- Schedule daily at 23:55: CALL hostel_q5.pr_refresh_occupancy().
SELECT * FROM v_room_occupancy; SELECT * FROM occupancy_snapshot;